sites.find:
do {
    spawn->pos.y = (float)(y_offset / 12 + 128);
    if ((index & 1) != 0) {
        spawn->pos.x = 896.0f;
    } else {
        spawn->pos.x = 832.0f;
    }
    spawn->set_spawn(
        SPAWN_ID_DEN_ALIEN_BASIC_07,
        trigger_time_ms,
        1);

    trigger_time_ms += 500;
    y_offset += 768;
    ++spawn;
    ++index;
} while (index < 12);

